-- Pilgrim's Bounty: complete the Alliance and Horde capital camps.
-- Apply with pilgrims_bounty_stormwind.sql and the matching holiday scripts.
-- Reference camp positions were checked against sf_pro_world; duplicate chair rows are not imported.
-- Chairs use the tested independent layout, with terrain-aligned heights and a unique nearest table.
-- Existing Exodar and Silvermoon camps are retained.
-- https://www.wowhead.com/mop-classic/guide/holidays/pilgrims-bounty

-- Seasonal cooking trainers offer Apprentice Cooking (also repairs Stormwind).
DELETE FROM `npc_trainer` WHERE `entry` IN (34708,34710,34711,34712,34713,34714,34785,34786) AND `spell`=2551;

-- Keep the Silvermoon cranberry chair associated with its own table.
UPDATE `creature` SET `position_y`=-7220.0 WHERE `guid`=966 AND `id`=34823 AND `map`=530 AND `position_x` BETWEEN 9289 AND 9290;

DELETE FROM `game_event_creature` WHERE `eventEntry`=26 AND `guid` BETWEEN 9002000 AND 9002192;
DELETE FROM `creature` WHERE `guid` BETWEEN 9002000 AND 9002192 AND `id` IN (32820,32823,34644,34645,34653,34654,34676,34677,34678,34679,34681,34683,34684,34685,34708,34711,34712,34713,34714,34768,34812,34819,34822,34823,34824,35338,35340,35341,35342,35343);

-- Seasonal cooking fires and decorations; unrelated Brewfest objects are excluded.
DELETE FROM `game_event_gameobject` WHERE `eventEntry`=26 AND `guid` BETWEEN 9002000 AND 9002334;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9002000 AND 9002334 AND `id` IN (179968,180353,195164,195191,195192,195194,195195,195196,195197,195198,195199,195200,195212,195215,195303);

-- Stormwind scenery, preserving the already tested three-table camp.
-- Omit reference props that intersect our chairs/hostess; move the cooking fire clear of Jasper.
-- Retain vertically stacked hay bales rather than treating them as duplicate spawns.
DELETE FROM `game_event_gameobject` WHERE `eventEntry`=26 AND `guid` BETWEEN 9002400 AND 9002500;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9002400 AND 9002500 AND `id` IN (179968,180353,195164,195191,195192,195194,195195,195196,195197,195198,195199,195200,195212,195215,195303);
